// Renders real 3D thumbnails for hats with one shared offscreen renderer.
import * as THREE from 'three';
import { buildHat } from './engine/player.js';

const cache = new Map();
let renderer = null, scene = null, camera = null;

function ensure() {
  if (renderer) return;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = 160;
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, preserveDrawingBuffer: true });
  renderer.setSize(160, 160, false);
  scene = new THREE.Scene();
  scene.add(new THREE.AmbientLight(0xffffff, 1.3));
  const key = new THREE.DirectionalLight(0xffffff, 2.4);
  key.position.set(2.5, 3.5, 4);
  scene.add(key);
  const rim = new THREE.DirectionalLight(0x19c2ff, 1.0);
  rim.position.set(-3, 1.5, -3);
  scene.add(rim);
  camera = new THREE.PerspectiveCamera(34, 1, 0.1, 20);
  camera.position.set(0, 0.85, 2.5);
  camera.lookAt(0, 0.32, 0);
}

export function hatThumb(item) {
  if (cache.has(item.id)) return cache.get(item.id);
  ensure();
  const g = buildHat(item.mesh);
  g.rotation.y = 0.55;
  scene.add(g);
  renderer.render(scene, camera);
  const url = renderer.domElement.toDataURL();
  scene.remove(g);
  cache.set(item.id, url);
  return url;
}
